"""Character restriction and two explicitly defined periodic teaching models.

The square-lattice C4v p_x/p_y model and spin-1/2 Rashba model are original
minimal examples, not fitted materials or a 230-space-group band diagnosis.
All compatibility multiplicities are evaluated from representation matrices.
Wave vectors are dimensionless radians (lattice constant a = 1); energies use
one common arbitrary energy unit.  NumPy is the sole runtime dependency.
"""
from __future__ import annotations

import math
import numpy as np


I2 = np.eye(2, dtype=complex)
SX = np.array([[0, 1], [1, 0]], dtype=complex)
SY = np.array([[0, -1j], [1j, 0]], dtype=complex)
SZ = np.diag([1, -1]).astype(complex)
ROTATION = np.array([[0, -1], [1, 0]], dtype=float)
MIRROR = np.diag([1., -1.])
SOURCES = [
    {"title": "Bilbao: compatibility relations between little-group representations",
     "url": "https://test4.cryst.ehu.es/rep/rep_correlation_relations.html"},
    {"title": "Elcoro et al., Double crystallographic groups and their representations (2017)",
     "url": "https://arxiv.org/abs/1706.09272"},
    {"title": "Samokhin, Effective models of spin-orbit coupling in a 2D electron gas (2021)",
     "url": "https://arxiv.org/abs/2112.12657"},
]


def _clean(value):
    if isinstance(value, dict):
        return {key: _clean(item) for key, item in value.items()}
    if isinstance(value, np.ndarray):
        return _clean(value.tolist())
    if isinstance(value, (list, tuple)):
        return [_clean(item) for item in value]
    if isinstance(value, (complex, np.complexfloating)):
        return {"re": float(value.real), "im": float(value.imag)}
    if isinstance(value, (float, np.floating)):
        return float(value)
    if isinstance(value, np.integer):
        return int(value)
    if isinstance(value, np.bool_):
        return bool(value)
    return value


def _number(payload, key, default, lower, upper):
    value = payload.get(key, default)
    if (isinstance(value, bool) or not isinstance(value, (int, float))
            or not math.isfinite(value) or not lower <= value <= upper):
        raise ValueError(f"{key} 必须是 {lower} 至 {upper} 的有限实数")
    return float(value)


def _representations(double=False):
    """Generate C4v / its double cover from r and m, never from cached rows.

    Single: r^4=m^2=1, m r m^-1=r^-1.
    Double: r^4=m^2=bar(E), bar(E)^2=1.
    Single-valued irreps are lifted to the double cover when requested.
    """
    rotations = 8 if double else 4
    seeds = [
        ("A1", np.array([[1]], complex), np.array([[1]], complex)),
        ("A2", np.array([[1]], complex), np.array([[-1]], complex)),
        ("B1", np.array([[-1]], complex), np.array([[1]], complex)),
        ("B2", np.array([[-1]], complex), np.array([[-1]], complex)),
        ("E", ROTATION.astype(complex), SZ),
    ]
    if double:
        for twice_j in (1, 3):
            r = np.diag(np.exp([-1j * twice_j * math.pi / 4,
                                1j * twice_j * math.pi / 4]))
            seeds.append((f"E{twice_j}/2", r, 1j * SY))
    representations = []
    for label, r, m in seeds:
        matrices = [np.linalg.matrix_power(r, n) for n in range(rotations)]
        matrices += [np.linalg.matrix_power(r, n) @ m for n in range(rotations)]
        representations.append({"label": label, "dimension": len(r),
                                "matrices": matrices,
                                "characters": np.array([np.trace(u) for u in matrices])})
    return representations


def _compatibility(double, active):
    parents = _representations(double)
    subgroup_indices = [0, 8, 4, 12] if double else [0, 4]
    # Double Cs is generated by m: [1,m,m^2,m^3].  Its spinful eigenvalues
    # are +/-i since m^2=-1; the ordinary +/-1 characters remain in the table.
    eigenvalues = [1, -1, 1j, -1j] if double else [1, -1]
    labels = ["A'", "A''", "D+", "D-"] if double else ["A'", "A''"]
    line_characters = [np.array([z ** n for n in range(len(subgroup_indices))])
                       for z in eigenvalues]
    rows = []
    max_integer_error = 0.
    for parent in parents:
        restricted = parent["characters"][subgroup_indices]
        raw = [np.vdot(chi, restricted) / len(subgroup_indices) for chi in line_characters]
        multiplicities = [int(round(value.real)) for value in raw]
        max_integer_error = max(max_integer_error,
                                max(abs(raw[i] - multiplicities[i]) for i in range(len(raw))))
        branches = [{"label": label, "multiplicity": n, "dimension": 1}
                    for label, n in zip(labels, multiplicities) if n]
        rows.append({"parent": parent["label"], "dimension": parent["dimension"],
                     "restrictedCharacters": restricted, "multiplicities": multiplicities,
                     "innerProducts": raw, "branches": branches,
                     "dimensionSum": sum(multiplicities)})
    chars = np.array([parent["characters"] for parent in parents])
    gram = chars.conj() @ chars.T / len(chars[0])
    active_label = "E1/2" if double else "E"
    return {
        "parentGroup": "double C4v" if double else "C4v",
        "lineGroup": "double Cs" if double else "Cs",
        "formula": "n(α→β)=Σ[h∈H] conj(χβ(h)) χα(h) / |H|",
        "operations": ["1", "m_xz", "bar(1)", "bar(m_xz)"] if double else ["1", "m_xz"],
        "parentOrder": len(chars[0]), "lineOrder": len(subgroup_indices),
        "parentIrreps": [{key: item[key] for key in ("label", "dimension", "characters")}
                         for item in parents],
        "lineIrreps": [{"label": label, "dimension": 1, "mirrorEigenvalue": z,
                        "characters": chi}
                       for label, z, chi in zip(labels, eigenvalues, line_characters)],
        "rows": rows, "activeRows": [row for row in rows if row["parent"] == active_label],
        "active": active,
        "note": ("本模型的表示限制；E1/2、E3/2 和 D± 为此处定义的局部标签，不冒充 Bilbao 空间群标签。"
                 if double else "m_xz:(x,y)→(x,−y)，E 基为 (p_x,p_y)；A' 为镜面偶，A'' 为镜面奇。"),
        "integerResidual": max_integer_error,
        "orthogonalityResidual": float(np.max(np.abs(gram - np.eye(len(parents))))),
        "dimensionConserved": all(row["dimensionSum"] == row["dimension"] for row in rows),
    }


def _endpoint_compatibility(double, active):
    """Compute the X endpoint restrictions using its actual C2v matrices."""
    if double:
        r, m = -1j * SZ, 1j * SY
        matrices = [np.linalg.matrix_power(r, n) for n in range(4)]
        matrices += [np.linalg.matrix_power(r, n) @ m for n in range(4)]
        parents = [("X spinor", 2, matrices)]
        indices, labels, lambdas = [0, 4, 2, 6], ["A'", "A''", "D+", "D-"], [1, -1, 1j, -1j]
        operations = ["1", "C2z", "bar(1)", "bar(C2z)", "m_xz", "C2z m_xz", "bar(m_xz)", "bar(C2z m_xz)"]
        model_content = ["X spinor"]
    else:
        parents = []
        for name, rotation, mirror in (("A1", 1, 1), ("A2", 1, -1), ("B1", -1, 1), ("B2", -1, -1)):
            matrices = [np.array([[value]], dtype=complex) for value in (1, rotation, mirror, rotation * mirror)]
            parents.append((name, 1, matrices))
        indices, labels, lambdas = [0, 2], ["A'", "A''"], [1, -1]
        operations = ["1", "C2z", "m_xz", "m_yz"]
        model_content = ["B1", "B2"]
    line_chars = [np.array([z ** n for n in range(len(indices))]) for z in lambdas]
    rows = []
    for label, dimension, matrices in parents:
        chars = np.array([np.trace(matrix) for matrix in matrices])
        restricted = chars[indices]
        inners = [np.vdot(chi, restricted) / len(indices) for chi in line_chars]
        multiplicities = [int(round(inner.real)) for inner in inners]
        rows.append({"parent": label, "dimension": dimension, "characters": chars,
                     "restrictedCharacters": restricted, "innerProducts": inners,
                     "multiplicities": multiplicities,
                     "branches": [{"label": name, "dimension": 1, "multiplicity": n}
                                  for name, n in zip(labels, multiplicities) if n],
                     "dimensionSum": sum(multiplicities)})
    return {"parentGroup": "double C2v" if double else "C2v", "point": "X=(π,0)",
            "lineGroup": "double Cs" if double else "Cs",
            "formula": "n(α→β)=Σ[h∈H] conj(χβ(h)) χα(h) / |H|",
            "operations": operations,
            "lineIrreps": [{"label": label, "dimension": 1, "mirrorEigenvalue": z, "characters": chi}
                           for label, z, chi in zip(labels, lambdas, line_chars)], "rows": rows,
            "activeRows": [row for row in rows if row["parent"] in model_content],
            "active": active,
            "note": "X 的小余群矩阵经限制得到右半连接；自旋分支仅计算本模型的二维 spinor。"}


def hamiltonian(model, kx, ky, parameters):
    """Publicly testable 2D Hamiltonian; parameters have already been validated."""
    p = parameters
    epsilon = 2 * p["hopping"] * (2 - math.cos(kx) - math.cos(ky))
    if model == "c4v":
        dz = p["beta"] * (math.cos(ky) - math.cos(kx)) * (math.cos(kx) + math.cos(ky) - 1 - p["eta"])
        dx = 2 * p["gamma"] * math.sin(kx) * math.sin(ky) + p["mixing"]
        return epsilon * I2 + dz * SZ + dx * SX
    if model == "rashba":
        return (epsilon * I2 + p["soc"] * (math.sin(ky) * SX - math.sin(kx) * SY)
                + p["zeeman"] * SZ)
    raise ValueError("未知能带模型")


def _spectrum(model, kx, parameters, mirror_active):
    h = hamiltonian(model, kx, 0., parameters)
    values, vectors = np.linalg.eigh(h)
    mirror_observable = SY if model == "rashba" else SZ
    # A degenerate eigensolver may choose arbitrary vectors.  Resolve their
    # mirror character inside the degenerate subspace, not by a random gauge.
    if mirror_active and abs(values[1] - values[0]) < 1e-11:
        _, rotation = np.linalg.eigh(vectors.conj().T @ mirror_observable @ vectors)
        vectors = vectors @ rotation
    mirror = np.real(np.diag(vectors.conj().T @ mirror_observable @ vectors))
    spin = [[float(np.vdot(vectors[:, band], sigma @ vectors[:, band]).real)
             for sigma in (SX, SY, SZ)] for band in range(2)]
    residual = float(np.max(np.abs(h @ vectors - vectors @ np.diag(values))))
    return values, mirror, spin, residual


def _validation(model, parameters):
    r = np.diag(np.exp([-1j * math.pi / 4, 1j * math.pi / 4])) if model == "rashba" else ROTATION
    m = 1j * SY if model == "rashba" else SZ
    time_unitary = 1j * SY if model == "rashba" else I2
    residuals = {"rotationResidual": 0., "mirrorResidual": 0., "timeReversalResidual": 0.,
                 "hermiticityResidual": 0., "periodicityResidual": 0.}
    for kx, ky in ((.23, .47), (.91, -.32), (1.71, .86), (0., 0.), (math.pi, 0.)):
        h = hamiltonian(model, kx, ky, parameters)
        checks = {
            "rotationResidual": r @ h @ r.conj().T - hamiltonian(model, -ky, kx, parameters),
            "mirrorResidual": m @ h @ m.conj().T - hamiltonian(model, kx, -ky, parameters),
            "timeReversalResidual": time_unitary @ h.conj() @ time_unitary.conj().T - hamiltonian(model, -kx, -ky, parameters),
            "hermiticityResidual": h - h.conj().T,
            "periodicityResidual": hamiltonian(model, kx + 2 * math.pi, ky + 2 * math.pi, parameters) - h,
        }
        for name, difference in checks.items():
            residuals[name] = max(residuals[name], float(np.max(np.abs(difference))))
    residuals["timeReversalSquare"] = -1 if model == "rashba" else 1
    return residuals


def _connections(double, active, compatibility, endpoint):
    if double:
        nodes = [{"id": "gamma", "label": "Γ: E1/2", "column": 0, "dimension": 2},
                 {"id": "line-plus", "label": "Δ: D+ (m=+i)", "column": 1, "dimension": 1},
                 {"id": "line-minus", "label": "Δ: D− (m=−i)", "column": 1, "dimension": 1},
                 {"id": "x", "label": "X: 自旋双重态", "column": 2, "dimension": 2}]
        note = "Bz=0 时 Γ、X 是 TRIM；±i 镜面态在端点配对，路径内部一般分裂。"
    else:
        # At X, C2v operations are [1,C2z,m_xz,m_yz].  p_x (B1) and
        # p_y (B2) restrict to mirror even/odd respectively.
        nodes = [{"id": "gamma", "label": "Γ: E", "column": 0, "dimension": 2},
                 {"id": "line-plus", "label": "Δ: A' (m=+1)", "column": 1, "dimension": 1},
                 {"id": "line-minus", "label": "Δ: A'' (m=−1)", "column": 1, "dimension": 1},
                 {"id": "x-plus", "label": "X: B1 (p_x)", "column": 2, "dimension": 1},
                 {"id": "x-minus", "label": "X: B2 (p_y)", "column": 2, "dimension": 1}]
        note = "连接只约束表示分支，不单独保证内部交叉；本模型的交叉还取决于 β、η 和能量排序。"
    line_ids = {"A'": "line-plus", "A''": "line-minus", "D+": "line-plus", "D-": "line-minus"}
    endpoint_ids = {"B1": "x-plus", "B2": "x-minus", "X spinor": "x"}
    edges = [{"from": "gamma", "to": line_ids[branch["label"]],
              "label": str(branch["multiplicity"]), "multiplicity": branch["multiplicity"]}
             for row in compatibility["activeRows"] for branch in row["branches"]]
    edges += [{"from": line_ids[branch["label"]], "to": endpoint_ids[row["parent"]],
               "label": str(branch["multiplicity"]), "multiplicity": branch["multiplicity"]}
              for row in endpoint["activeRows"] for branch in row["branches"]]
    if not active:
        note = "所选镜面对称性已破缺：此图仅供零扰动母相参考，不能当作当前能带的有效对称标签。"
    return {"nodes": nodes, "edges": edges, "active": active, "note": note,
            "isTopologicalDiagnosis": False}


def run(payload):
    if not isinstance(payload, dict):
        raise ValueError("输入必须是 JSON 对象")
    model = payload.get("model", "c4v")
    if model not in ("c4v", "rashba"):
        raise ValueError("model 仅支持 c4v 或 rashba")
    samples = payload.get("samples", 121)
    if isinstance(samples, bool) or not isinstance(samples, int) or not 21 <= samples <= 501:
        raise ValueError("samples 必须是 21 至 501 的整数")
    p = {key: _number(payload, key, default, lower, upper)
         for key, default, lower, upper in (
             ("hopping", 1, 0, 5), ("beta", 1, -5, 5), ("gamma", .6, -5, 5),
             ("eta", 0, -1.5, 1.5), ("mixing", 0, -3, 3),
             ("soc", .6, -3, 3), ("zeeman", 0, -3, 3))}
    double = model == "rashba"
    perturbation = p["zeeman"] if double else p["mixing"]
    active = perturbation == 0
    compatibility = _compatibility(double, active)
    endpoint = _endpoint_compatibility(double, active)
    ks = np.linspace(0., math.pi, samples)
    bands = [{"index": n, "label": "低能支" if n == 0 else "高能支", "energies": [],
              "mirror": [], "mirrorLabels": [], "spin": []} for n in range(2)]
    diagonalization_residual = 0.
    for kx in ks:
        values, mirrors, spins, residual = _spectrum(model, kx, p, active)
        diagonalization_residual = max(diagonalization_residual, residual)
        for n, band in enumerate(bands):
            band["energies"].append(values[n])
            band["mirror"].append(mirrors[n])
            band["spin"].append(spins[n])
            band["mirrorLabels"].append(("D+ (+i)" if mirrors[n] > 0 else "D− (−i)") if active and double
                                        else ("A' (+1)" if mirrors[n] > 0 else "A'' (−1)") if active else "混合态")
    warnings = ["二维方格教学模型：不计算真实材料能带，不提供全 230 空间群相容关系或拓扑指标。",
                "能量为共同任意单位；k 坐标为弧度，晶格常数 a=1。"]
    if not active:
        warnings.append("镜面对称性已破缺，特征标表与连接图仅表示零扰动母相；当前态只显示镜面期望值。")
    crossings = []
    if double:
        gap = 2 * abs(p["zeeman"])
        if p["soc"] == 0 and active:
            crossings.append({"kind": "extended", "label": "整条路径自旋简并", "t": None,
                              "gap": 0., "protected": False,
                              "explanation": "α=Bz=0 时 H=εI，额外自旋旋转对称性使所有 k 简并。"})
        else:
            for label, t in (("Γ", 0.), ("X", 1.)):
                crossings.append({"kind": "kramers" if active else "zeeman-gap", "label": label,
                                  "t": t, "kx": t * math.pi, "gap": gap, "protected": active,
                                  "explanation": "TRIM 上 T²=−1 保证二重简并。" if active else "Bz 破坏时间反演，原 TRIM 双重态间隙为 2|Bz|。"})
        explanation = [
            "镜面算符 M=iσy 满足 M²=−I，因此自旋镜面本征值为 ±i。",
            "将 E1/2 的特征标 [2,0,−2,0] 限制到 double Cs，与四个一维特征标作内积，得到 D+⊕D−。",
            "沿 ky=0，H=εI−α sin(kx)σy+Bzσz。Bz=0 时分裂为 ε±|α sin(kx)|。",
            "时间反演 T=iσyK 将 k 与 −k 配对；只在 Γ、X 这两个本路径的 TRIM 上保证同一 k 的 Kramers 简并。",
            "α=0 的整条自旋简并是额外自旋对称性；不能把所有 k 都称为时间反演不变点。",
        ]
        formula = "H(k)=2t[2−cos(kx)−cos(ky)]I+α[sin(ky)σx−sin(kx)σy]+Bzσz"
        basis = ["|↑z⟩", "|↓z⟩"]
        line_formula = "E±(k,0)=2t(1−cos k)±sqrt(α² sin²k+Bz²)"
    else:
        gap = 2 * abs(p["mixing"])
        crossings.append({"kind": "endpoint-degeneracy" if active else "hybridization-gap",
                          "label": "Γ", "t": 0., "kx": 0., "gap": gap, "protected": active,
                          "explanation": "C4v 的二维 E 表示保证 Γ 端点简并。" if active else "δσx 破坏原 C4v，Γ 双重态也分裂。"})
        if p["beta"] == 0:
            crossings.append({"kind": "extended" if active else "parallel-gap", "label": "整条路径",
                              "t": None, "gap": gap, "protected": False,
                              "explanation": "β=0 时此路径 d_z=0；这是额外参数调谐，不是相容关系强制的内部交叉。"})
        elif -1 < p["eta"] < 1:
            k_cross = math.acos(p["eta"])
            crossings.append({"kind": "mirror-protected" if active else "avoided-crossing",
                              "label": "内部交叉" if active else "反交叉", "t": k_cross / math.pi,
                              "kx": k_cross, "gap": gap, "protected": active,
                              "energy": 2 * p["hopping"] * (1 - p["eta"]),
                              "explanation": "不同镜面本征值禁止杂化；交叉位置由 cos(kx)=η 决定。" if active
                                             else "δ 混合镜面奇偶态，在原交叉处打开 2|δ| 的间隙。"})
        elif p["eta"] == -1:
            crossings.append({"kind": "tuned-endpoint" if active else "hybridization-gap",
                              "label": "X", "t": 1., "kx": math.pi, "gap": gap, "protected": False,
                              "explanation": "η=−1 将交叉调到 X；X 的两个一维表示本身不强制简并。"})
        explanation = [
            "C4v 的 E 表示使用 (p_x,p_y) 基；镜面 m_xz 的矩阵为 diag(+1,−1)。",
            "限制到 Cs 后 χE=[2,0]；分别与 A'=[1,1]、A''=[1,−1] 内积，得到 1 和 1。",
            "相容关系 E↓Cs=A'⊕A'' 决定两个分支的对称性，不决定其能量，也不单独强制内部交叉。",
            "沿 ky=0，d_z=β(1−cos k)(cos k−η)。β≠0 且 −1<η<1 时，两种镜面态在 acos(η) 相交。",
            "加入 δσx 后镜面对称破缺，原交叉处 E+−E−=2|δ|；能带排序改变时不能误把序号当作固定表示。",
        ]
        formula = "H(k)=εI+β(cos ky−cos kx)(cos kx+cos ky−1−η)σz+[2γ sin kx sin ky+δ]σx; ε=2t(2−cos kx−cos ky)"
        basis = ["p_x", "p_y"]
        line_formula = "E±(k,0)=2t(1−cos k)±sqrt([β(1−cos k)(cos k−η)]²+δ²)"
    validation = _validation(model, p)
    validation.update({"diagonalizationResidual": diagonalization_residual,
                       "characterIntegerResidual": compatibility["integerResidual"],
                       "characterOrthogonalityResidual": compatibility["orthogonalityResidual"],
                       "dimensionConserved": compatibility["dimensionConserved"],
                       "mirrorSymmetryPresent": active,
                       "timeReversalPresent": active if double else True,
                       "note": "非零对称残差可用于观察人为破缺；不应把破缺残差当作求解器误差。"})
    return _clean({
        "model": model, "title": "Rashba 自旋分裂与 Kramers 配对" if double else "C4v 表示分支与镜面保护交叉",
        "parameters": {**p, "samples": samples}, "scope": "selected-square-lattice-teaching-model",
        "warnings": warnings, "sources": SOURCES,
        "path": {"label": "Γ–X", "coordinates": (ks / math.pi),
                 "kpoints": [[kx, 0.] for kx in ks], "ticks": [{"t": 0., "label": "Γ"}, {"t": 1., "label": "X"}],
                 "coordinateNote": "横轴 t=kx/π；ky=0；Γ=(0,0)，X=(π,0)"},
        "bands": bands, "compatibility": compatibility, "endpointCompatibility": endpoint,
        "connections": _connections(double, active, compatibility, endpoint),
        "crossings": crossings, "validation": validation,
        "summary": {"bandCount": 2, "sampleCount": samples, "mirrorActive": active,
                    "referenceGroup": "double C4v → double Cs" if double else "C4v → Cs",
                    "perturbationGap": gap, "gapLabel": "TRIM 能隙 2|Bz|" if double else "原交叉处能隙 2|δ|",
                    "timeReversal": active if double else True, "spinful": double,
                    "energyUnit": "模型能量单位"},
        "hamiltonian": {"basis": basis, "formula": formula, "lineEigenvalues": line_formula,
                        "mirrorOperator": "iσy" if double else "σz",
                        "timeReversalOperator": "iσy K" if double else "K",
                        "mirrorObservable": "<σy>；乘 i 才是 <M>" if double else "<σz>=<M>",
                        "spinNote": "spin 字段为 <σx,σy,σz>，实际自旋为 ħ/2 倍。" if double else "spin 字段仅为轨道赝自旋，不是电子真实自旋。"},
        "explanation": explanation,
    })
